from __future__ import annotations

from typing import Any, List, Optional

from h11 import PRODUCT_ID
from pydantic import BaseModel


class Product(BaseModel):
    id: int
    name: str
    productName: str
    partNumber: str
    formattedPartNumber: Any
    url: str
    brandCode: str
    brandName: str
    brandLabel: str
    primaryImageIndex: int
    rating: float
    ratingCount: int
    ratingUrl: str
    reviewUrl: str
    listPrice: str
    listPriceAmount: float
    discountedPrice: str
    discountedPriceAmount: float
    hidePrice: bool
    productFlag: Any
    discountType: int
    discountDisplayType: int
    discountMessage: str
    isInCartDiscount: bool
    salesDiscountPercentage: float
    autoApplyDiscountPercentage: Any
    specialDealInfo: Any
    ratingStarsMap: List[float]
    isInGroup: bool
    currencySymbol: Any
    isCurrencySymbolOnLeft: Any
    salePriceAmount: Any
    salePriceFormatted: Any
    groupId: int
    trendingMetric: Any
    recentActivityMessage: Any
    recentActivityCount: Any
    isOutOfStock: bool
    backInStockDate: Any
    isNew: bool
    prohibited: bool
    isNotAvailable: bool
    isNoPO: bool
    isDiscontinued: bool


class Model(BaseModel):
    products: List[Product]
    total: int

